Here is the brute-force MaxCut solution for the `5cycle` graph.

```python
#!/usr/bin/env python3
# MaxCut brute-force for graph '5cycle'.
# Edges: [(0, 1), (1, 2), (2, 3), (3, 4), (4, 0)]

def maxcut_value(edges):
    nodes = sorted(set(n for e in edges for n in e))
    n = len(nodes)
    best = 0
    for mask in range(1 << n):
        cut = 0
        for u, v in edges:
            if ((mask >> u) & 1) != ((mask >> v) & 1):
                cut += 1
        best = max(best, cut)
    return best


def main():
    edges = [(0, 1), (1, 2), (2, 3), (3, 4), (4, 0)]
    print(maxcut_value(edges))

if __name__ == "__main__":
    main()
```

